package com.bank.codemig.service;

import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.logging.Logger;

// Shortest one-letter transformation chain via breadth-first search.
public class ProductCodeMigrationService {
    private static final Logger log = Logger.getLogger(ProductCodeMigrationService.class.getName());

    public int shortestChain(String begin, String end, List<String> dictionary) {
        Set<String> dict = new HashSet<>(dictionary);
        if (!dict.contains(end)) {                        // end not reachable
            log.warning(() -> "End code " + end + " not in catalogue");
            return 0;
        }
        Queue<String> queue = new ArrayDeque<>();
        queue.add(begin);
        int steps = 1;                                    // begin counts as step 1
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int s = 0; s < levelSize; s++) {          // process one BFS level
                String word = queue.poll();
                if (word.equals(end)) {
                    final int found = steps;
                    log.info(() -> "Shortest code chain length = " + found);
                    return steps;
                }
                char[] arr = word.toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char old = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {    // try every one-letter change
                        arr[i] = c;
                        String next = new String(arr);
                        if (dict.remove(next)) queue.add(next); // valid + unvisited
                    }
                    arr[i] = old;                          // restore position
                }
            }
            steps++;                                       // advance to next level
        }
        log.warning(() -> "No valid chain from " + begin + " to " + end);
        return 0;
    }
}
