package com.bank.codemig;

import com.bank.codemig.service.ProductCodeMigrationService;
import java.util.List;
import java.util.logging.Logger;

public class CodeMigrationApplication {
    private static final Logger log = Logger.getLogger(CodeMigrationApplication.class.getName());

    public static void main(String[] args) {
        ProductCodeMigrationService service = new ProductCodeMigrationService();
        List<String> catalogue = List.of("hot", "dot", "dog", "lot", "log", "cog");
        int len = service.shortestChain("hit", "cog", catalogue);
        log.info(() -> "Final migration chain length = " + len);
    }
}
